export const eligibleGeography=(l,pathway)=>!l.option||!pathway||pathway.landscapes.includes(l.option);
export const KEY='crash-course-geography-a-v1';
export function restore(raw){let v={};try{v=JSON.parse(raw)||{};if(v.version!==1)v={};}catch{}return {version:1,lessonId:lessons.some(l=>l.id===v.lessonId)?v.lessonId:lessons[0].id,lessons:v.lessons&&typeof v.lessons==='object'&&!Array.isArray(v.lessons)?v.lessons:{},concepts:v.concepts&&typeof v.concepts==='object'&&!Array.isArray(v.concepts)?v.concepts:{},pathway:validPath(v.pathway)?v.pathway:null,review:v.review&&Array.isArray(v.review.ids)&&v.review.ids.length>0&&v.review.ids.every(id=>lessons.some(l=>[...l.check,...l.practice].some(q=>q.id===id)))?v.review:null};}
export function validPath(p){return !!p&&Array.isArray(p.landscapes)&&p.landscapes.length===2&&new Set(p.landscapes).size===2&&p.landscapes.every(x=>['coasts','rivers','glaciers'].includes(x))&&['energy','water'].includes(p.resource)&&['rivers','coasts'].includes(p.physical)&&['urban','rural'].includes(p.human);}
export const geoGates=(l,p)=>[l.cards.every((_,i)=>p.seen.includes(i)),l.tasks.every((_,i)=>p.passed.includes(i))&&requirements[l.model].every(x=>p.observed.includes(x)),l.practice.every(q=>p.practice[q.id]?.correct),l.check.every(q=>p.checks[q.id]!==undefined)&&l.check.filter(q=>p.checks[q.id]===q.answer).length/l.check.length>=.8];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function choiceIndices(id,count,run=1){let seed=2166136261;for(const c of id+':'+run)seed=Math.imul(seed^c.charCodeAt(0),16777619);const a=Array.from({length:count},(_,i)=>i);for(let i=count-1;i>0;i--){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const j=(seed>>>0)%(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
export function createGeographyStudio({root,modal,closeModal,onProgress}){let raw;try{raw=localStorage.getItem(KEY);}catch{}const s=restore(raw);if(!eligibleGeography(lessons.find(l=>l.id===s.lessonId),s.pathway))s.lessonId=lessons[0].id;let mode=s.review?'review':'lesson',run=s.review?{questions:s.review.ids.filter(id=>lessons.some(l=>eligibleGeography(l,s.pathway)&&[...l.check,...l.practice].some(q=>q.id===id))).map(id=>lessons.flatMap(l=>[...l.check,...l.practice]).find(q=>q.id===id)),answers:s.review.answers||{},index:Math.min(s.review.index||0,s.review.ids.length-1)}:null,frame=0,generation=0;const $=sel=>root.querySelector(sel),$$=sel=>[...root.querySelectorAll(sel)],lesson=()=>lessons.find(l=>l.id===s.lessonId);
 if(run&&!run.questions.length){run=null;mode='lesson';}else if(run)run.index=Math.min(run.index,run.questions.length-1);
 const state=l=>{const d={stage:0,card:0,seen:[],observed:[],selection:null,task:0,passed:[],practice:{},pi:0,checks:{},ci:0};return s.lessons[l.id]??=d;};
 const gates=geoGates;
 const available=()=>lessons.filter(l=>eligibleGeography(l,s.pathway));
 const contextLesson=()=>mode==='review'&&run?lessons.find(l=>[...l.check,...l.practice].some(q=>q.id===run.questions[run.index]?.id))||lesson():lesson();
 const activeTopic=()=>topics.find(t=>t.id===contextLesson().topicId);
 const availableTopics=()=>topics.filter(t=>available().some(l=>l.topicId===t.id));
 function getProgress(){const rows=available().map(l=>{const p=state(l),gaps=[],due=[];for(const id of new Set([...l.practice,...l.check].map(q=>q.concept))){const c=s.concepts[id];if(!c)continue;const item={id,label:id.split('.').pop().replaceAll('-',' ').replace(/^./,c=>c.toUpperCase())};if(c.needsReview)gaps.push(item);if(c.needsReview||c.due<=Date.now())due.push(item);}const a={total:0,correct:0},b={total:0,correct:0};for(const q of l.practice)if(p.practice[q.id]){a.total++;if(p.practice[q.id].first===q.answer)a.correct++;}for(const q of l.check)if(p.checks[q.id]!==undefined){b.total++;if(p.checks[q.id]===q.answer)b.correct++;}return {id:l.id,title:l.title,topicId:l.topicId,stages:gates(l,p),started:!!(p.seen.length||p.observed.length||Object.keys(p.practice).length||Object.keys(p.checks).length),practice:a,check:b,gaps,due};});return {...summarise(rows,availableTopics()),subject:'Geography',scope:'Pearson Edexcel Geography A · 1GA0'+(s.pathway?' · chosen pathway':' · exploring built topics'),scopeNote:'Totals cover built lessons in your pathway. The rest of the course is being developed.',practiceLabel:'Practice first tries'};}
 function save(){s.review=mode==='review'&&run?{ids:run.questions.map(q=>q.id),answers:run.answers,index:run.index}:null;let ok=true;try{localStorage.setItem(KEY,JSON.stringify(s));}catch{ok=false;}const x=getProgress();onProgress?.({done:x.completed,total:x.total,due:x.due.length,storage:ok,topic:activeTopic().title});}
 function stop(){cancelAnimationFrame(frame);generation++;}
 function feedback(t,error=false){const f=$('#gFeedback');if(f){f.textContent=t;f.classList.toggle('error',error);}}
 function model(l,p){const panel=$('#gPanel');if(!panel)return;const keys=requirements[l.model],timeModel=l.model.startsWith('weather-')||l.model.startsWith('glacier-')||l.model.startsWith('coast-')||(l.model.startsWith('river-')&&l.model!=='river-courses');p.selection=p.stage===0&&l.cardViews?.[p.card]?l.cardViews[p.card]:keys.includes(p.selection)?p.selection:keys[0];panel.innerHTML=`<div class="eyebrow">${l.model==='swanage'?'EVIDENCE EXPLORER':'INTERACTIVE MODEL'}</div><div id="gScene"></div><div class="geo-controls">${controls(l.model)}</div>${l.model==='process'?'<button class="scene-button" id="gPlay">Pause</button><label class="geo-loop"><input type="checkbox" id="gLoop" checked> Loop</label>':''}${timeModel?'<div class="geo-controls"><button class="scene-button" id="gCoastPlay">Pause</button><label class="geo-loop"><input type="checkbox" id="gCoastLoop" checked> Loop</label><button class="scene-button" data-coast-step="0">Beginning</button><button class="scene-button" data-coast-step="0.5">Middle</button><button class="scene-button" data-coast-step="1">End</button></div>':''}${l.model==='rocks'?'<button class="scene-button" id="gRockReference">Compare rock textures ↗</button>':''}<p class="geo-caption" id="gModelNote">${l.model==='swanage'?'Historical photograph and simplified supporting diagrams. Read each source caption.':'Original teaching diagram; symbolic and not to scale. Use the labelled controls as well as colour.'}</p>`;
  let onModelView=()=>{};const draw=(sel)=>{p.selection=sel;$('#gScene').innerHTML=scene(l.model,sel,Number(sel)||0);$$('[data-geo-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.geoView===sel)));if(p.stage===1&&!p.observed.includes(sel)){p.observed.push(sel);save();$('#gObservation').textContent=`Views compared: ${p.observed.length} / ${keys.length}`;}$('#gModelNote').textContent=l.model==='weather-uk-history'&&sel!=='millennium'?'Measured Central England temperature data. Region, dates, units and source above.':(l.model==='glacier-thirlmere'&&sel==='photo'||l.model==='river-falls'&&sel==='photo'||l.model==='river-tees-study'&&sel==='highforce')?'Genuine dated photograph. Attribution and evidence limits above.':l.model==='river-weather'&&sel==='record'?'Two dated EA water-level values, with source and units above. Not a live service.':l.model==='swanage'?'Historical photograph and simplified supporting diagrams. Read each source caption.':'Original teaching diagram; symbolic and not to scale. Use the labelled controls as well as colour.';onModelView(sel);};
  if(l.model==='rocks')$('#gRockReference').onclick=()=>modal(`<h2>Compare rock textures</h2><p>AI-generated photoreal illustration · typical appearances, not verified specimens. Colour and texture vary; use origin and other evidence too. Sizes are not comparable.</p><img src="./geography/images/rock-textures-v1.png" width="1024" height="1536" style="display:block;width:100%;height:auto;border-radius:12px" alt="Six illustrative specimens: coarse pink, white and black granite; dark fine-grained basalt; sandy sandstone; white chalk; flat-cleaving slate; shiny foliated schist."><p>Look for coarse crystals, sand grains, cleavage and aligned minerals. Return to the model to compare each rock’s origin.</p>`);
  draw(p.selection);$$('[data-geo-view]').forEach(b=>b.onclick=()=>draw(b.dataset.geoView));
  if(timeModel){let playing=isProcessView(l.model,p.selection)&&!matchMedia('(prefers-reduced-motion: reduce)').matches,position=0,last=performance.now(),paint=0;const ticket=generation,button=$('#gCoastPlay');const drawFrame=()=>{$('#gScene').innerHTML=scene(l.model,p.selection,position);};button.parentElement.hidden=!isProcessView(l.model,p.selection);onModelView=sel=>{position=0;playing=isProcessView(l.model,sel)&&!matchMedia('(prefers-reduced-motion: reduce)').matches;button.parentElement.hidden=!isProcessView(l.model,sel);button.textContent=playing?'Pause':'Play';last=performance.now();drawFrame();};button.textContent=playing?'Pause':'Play';button.onclick=()=>{playing=!playing;if(playing&&position>=1)position=0;button.textContent=playing?'Pause':'Play';last=performance.now();};$$('[data-coast-step]').forEach(b=>b.onclick=()=>{playing=false;position=Number(b.dataset.coastStep);button.textContent='Play';drawFrame();});const tick=now=>{if(ticket!==generation||root.hidden||!panel.isConnected)return;if(playing&&!document.hidden){position+=(now-last)/5000;if(position>=1){if($('#gCoastLoop').checked)position%=1;else{position=1;playing=false;button.textContent='Play';}}if(now-paint>40){drawFrame();paint=now;}}last=now;frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);}
  if(l.model==='process'){let playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=performance.now(),elapsed=0;const ticket=generation;$('#gPlay').textContent=playing?'Pause':'Play';$('#gPlay').onclick=()=>{playing=!playing;$('#gPlay').textContent=playing?'Pause':'Play';last=performance.now();};const tick=now=>{if(ticket!==generation||root.hidden||!panel.isConnected)return;if(playing&&!document.hidden){elapsed+=now-last;if(elapsed>=2600){elapsed=0;const n=(Number(p.selection)+1);if(n>2&&!$('#gLoop').checked){playing=false;$('#gPlay').textContent='Play';}else draw(String(n%3));}}last=now;frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);}
 }
 function render(){stop();cancelQuestionAdvance();root.innerHTML=`<section class="intro"><div><div class="eyebrow">GEOGRAPHY A · ${esc(activeTopic().title.toUpperCase())}</div><h1>${mode==='lesson'?esc(lesson().title):'Recall review'}</h1></div><div class="lesson-meta">◷ ${lesson().minutes} min</div></section><div class="lesson-toolbar"><button class="text-button" id="gLessons">Lessons</button><button class="text-button" id="gPath">Your pathway${s.pathway?'':' · choose options'}</button><button class="text-button" id="gNext">Next lesson →</button></div><nav class="steps" aria-label="Lesson stages">${['Discover','Investigate','Practise','Check'].map((t,i)=>`<button data-gstage="${i}"><b>0${i+1}</b>${t}</button>`).join('')}</nav><section class="workspace"><div class="scene-panel geo-panel" id="gPanel"></div><article class="activity"><div class="eyebrow" id="gKicker"></div><h2 id="gTitle"></h2><div id="gBody"></div><div id="gFeedback" role="status" aria-live="polite"></div><div class="activity-footer"><span id="gHint"></span><button class="primary" id="gContinue">Continue →</button></div></article></section><footer><button class="text-button" id="gSources">Sources & model notes</button></footer>`;
 $('#gLessons').onclick=()=>openLessons();$('#gPath').onclick=openPathway;$('#gSources').onclick=openSources;$('#gNext').onclick=()=>{const list=available(),i=list.indexOf(lesson());i<list.length-1?openLesson(list[i+1].id):openMap();};$$('[data-gstage]').forEach(b=>b.onclick=()=>{mode='lesson';state(lesson()).stage=Number(b.dataset.gstage);render();});
 if(mode==='review'){root.querySelector('.steps').hidden=true;question(run.questions[run.index],run.answers[run.questions[run.index].id],v=>{const q=run.questions[run.index];if(run.answers[q.id]!==undefined)return;run.answers[q.id]=v;recordConcept(s,q.concept,v===q.answer,Date.now(),true);save();render();},run.answers[run.questions[run.index].id]!==undefined);const q=run.questions[run.index],a=run.answers[q.id];if(a!==undefined)feedback((a===q.answer?'Correct. ':'Revisit this. ')+q.why,a!==q.answer);$('#gHint').textContent=`Recall ${run.index+1} / ${run.questions.length}`;$('#gContinue').onclick=()=>{if(run.answers[q.id]===undefined)return;if(++run.index>=run.questions.length){mode='lesson';render();modal('<h2>Review recorded</h2><p>Correct recall schedules the next visit. Missed concepts stay on your review list.</p>');}else render();};questionFlow($('#gContinue'),{answered:a!==undefined,automatic:a===q.answer,next:()=>$('#gContinue').click(),guard:()=>!root.hidden&&mode==='review'});save();return;}
 const l=lesson(),p=state(l),done=gates(l,p);p.stage=Math.max(0,Math.min(3,p.stage));$$('[data-gstage]').forEach((b,i)=>{b.classList.toggle('selected',p.stage===i);b.setAttribute('aria-current',p.stage===i?'step':'false');if(done[i])b.querySelector('b').textContent='✓';});$('#gKicker').textContent=['DISCOVER','INVESTIGATE','PRACTISE','CHECK'][p.stage];root.querySelector('.workspace').classList.toggle('question-mode',p.stage>=2);
 if(p.stage===0){const c=l.cards[p.card]||l.cards[0];$('#gTitle').textContent=c[0];$('#gBody').innerHTML=`<p>${esc(c[1])}</p><div class="reading-dots">${l.cards.map((_,i)=>`<button data-gcard="${i}" aria-label="Explanation ${i+1}" class="${i===p.card?'current':''}">${i+1}</button>`).join('')}</div>`;$$('[data-gcard]').forEach(b=>b.onclick=()=>{p.card=Number(b.dataset.gcard);render();});$('#gContinue').onclick=()=>{if(!p.seen.includes(p.card))p.seen.push(p.card);const unread=l.cards.findIndex((_,i)=>!p.seen.includes(i));if(unread<0){p.stage=1;if(l.cardViews)p.selection=requirements[l.model][0];}else p.card=unread;render();};model(l,p);}
 else if(p.stage===1){const i=Math.min(p.task,l.tasks.length-1),t=l.tasks[i];$('#gTitle').textContent='Explore, compare, explain';$('#gBody').innerHTML=`<p id="gObservation">Views compared: ${p.observed.length} / ${requirements[l.model].length}</p><p>${esc(t[0])}</p><div class="choices">${choiceIndices(t[0],t[1].length).map(j=>`<button class="choice" data-gtask="${j}" ${p.passed.includes(i)?'disabled':''}>${esc(t[1][j])}</button>`).join('')}</div>`;$$('[data-gtask]').forEach(b=>b.onclick=()=>{if(p.passed.includes(i))return;if(Number(b.dataset.gtask)!==t[2])return feedback('Look again at the evidence and the process described.',true);p.passed.push(i);$$('[data-gtask]').forEach(b=>b.disabled=true);save();feedback('Correct. Use the model controls to compare the views.');});$('#gHint').textContent=`Challenge ${i+1} / ${l.tasks.length}`;$('#gContinue').onclick=()=>{if(!p.passed.includes(i))return feedback('Answer this challenge first.',true);if(i<l.tasks.length-1)p.task++;else if(!requirements[l.model].every(x=>p.observed.includes(x)))return feedback('Compare every labelled model view before moving on.',true);else p.stage=2;render();};model(l,p);}
 else if(p.stage===2){p.pi=Math.min(p.pi,l.practice.length-1);const q=l.practice[p.pi],a=p.practice[q.id];question(q,a?.choice,v=>{if(a?.correct)return;const old=p.practice[q.id];p.practice[q.id]={choice:v,first:old?.first??v,correct:v===q.answer};recordConcept(s,q.concept,v===q.answer);save();render();},!!a?.correct);if(a)feedback((a.correct?'Correct. ':'Try again. ')+q.why,!a.correct);$('#gHint').textContent=`Practice ${p.pi+1} / ${l.practice.length}`;$('#gContinue').onclick=()=>{if(!p.practice[q.id]?.correct)return;if(p.pi<l.practice.length-1)p.pi++;else p.stage=3;render();};questionFlow($('#gContinue'),{answered:!!a?.correct,next:()=>$('#gContinue').click(),guard:()=>!root.hidden&&mode==='lesson'&&state(l).stage===2});}
 else {p.ci=Math.min(p.ci,l.check.length-1);const q=l.check[p.ci],a=p.checks[q.id];question(q,a,v=>{if(a!==undefined)return;p.checks[q.id]=v;recordConcept(s,q.concept,v===q.answer);save();render();},a!==undefined);if(a!==undefined)feedback('Answer recorded.');$('#gHint').textContent=`Independent check ${p.ci+1} / ${l.check.length}`;$('#gContinue').textContent=p.ci===l.check.length-1?'See results →':'Next question →';$('#gContinue').onclick=()=>{if(p.checks[q.id]===undefined)return;if(p.ci<l.check.length-1){p.ci++;render();}else results(l,p);};questionFlow($('#gContinue'),{answered:a!==undefined,delay:650,next:()=>$('#gContinue').click(),guard:()=>!root.hidden&&mode==='lesson'&&state(l).stage===3});}
 save();}
 function question(q,value,answer,locked){$('#gPanel').innerHTML='';root.querySelector('.workspace').classList.add('question-mode');$('#gTitle').textContent=q.prompt;$('#gBody').innerHTML=`${q.cet?climateGraph(q.cet):''}${q.gauge?gaugeTable(false):''}${q.highForce?highForcePhoto(false):''}${q.thirlmere?thirlmerePhoto(false):''}${q.hydrograph?hydrograph():''}${q.photo?'<figure style="margin:0 0 24px"><img src="./geography/images/old-harry-nilfanion.jpg" width="4288" height="2848" style="width:100%;max-width:600px;height:auto;border-radius:12px" alt="Photograph from the sea with pale cliffs, openings near the water and detached rock toward the left."><figcaption>Old Harry Rocks · 17 October 2013 · <a href="https://commons.wikimedia.org/wiki/File:Old_Harry_Rocks_(2535).jpg" target="_blank" rel="noopener">Nilfanion / Wikimedia UK</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> · unchanged.</figcaption></figure>':''}<div class="choices">${choiceIndices(q.id,q.options.length,1+(state(lesson()).history?.length||0)).map(i=>`<button class="choice ${value===i?'selected':''}" data-ganswer="${i}" ${locked?'disabled':''}>${esc(q.options[i])}</button>`).join('')}</div>`;$$('[data-ganswer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.ganswer)));}
 function results(l,p){cancelQuestionAdvance();const score=Math.round(l.check.filter(q=>p.checks[q.id]===q.answer).length/l.check.length*100);modal(`<h2>${score}% · ${gates(l,p).every(Boolean)?'Lesson complete':'Keep building'}</h2><p>Completion needs all four stages and at least80% on Check. Review the explanations below.</p>${l.check.map(q=>`<details class="result-row"><summary>${p.checks[q.id]===q.answer?'✓':'↻'} ${esc(q.prompt)}</summary><p>${esc(q.why)} Correct answer: ${esc(q.options[q.answer])}</p></details>`).join('')}<button class="primary" id="gRetake">Try check again</button>`);document.getElementById('gRetake').onclick=()=>{(p.history??=[]).push({...p.checks});p.checks={};p.ci=0;closeModal();render();};}
 function openLesson(id,stage){if(!available().some(l=>l.id===id))return;s.lessonId=id;mode='lesson';if(stage!==undefined)state(lesson()).stage=stage;closeModal();render();}
 function openLessons(id=lesson().topicId){cancelQuestionAdvance();const t=availableTopics().find(t=>t.id===id)||availableTopics()[0];modal(`<span class="eyebrow">GEOGRAPHY A · ${!available().some(l=>l.topicId===t.id&&l.option)?'SHARED CORE':t.id==='geography.a.rivers'?'RIVERS OPTION':t.id==='geography.a.glaciers'?'GLACIATED UPLANDS OPTION':'COASTS OPTION'}</span><h2>${esc(t.title)}</h2><div class="lesson-list">${available().filter(l=>l.topicId===t.id).map((l,i)=>`<button class="lesson-row" data-glesson="${l.id}"><span>${i+1}</span><span><b>${esc(l.title)}</b><small>${gates(l,state(l)).every(Boolean)?'Completed':'25 min'}</small></span><span>→</span></button>`).join('')}</div>`);document.querySelectorAll('[data-glesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.glesson));}
 function openMap(){cancelQuestionAdvance();modal(`<span class="eyebrow">GEOGRAPHY A</span><h2>Course map</h2>${availableTopics().map(t=>`<button class="topic-link" data-gtopic="${t.id}"><span>${esc(t.title)}</span><span>→</span></button>`).join('')}${!s.pathway?'<p>Exploring all built topics. Choose your pathway to match your exam options.</p>':''}<button class="text-button" id="gMapPath">Your pathway</button>`);document.querySelectorAll('[data-gtopic]').forEach(b=>b.onclick=()=>openLessons(b.dataset.gtopic));document.getElementById('gMapPath').onclick=openPathway;}
 function openPathway(){cancelQuestionAdvance();const p=s.pathway;modal(`<span class="eyebrow">EDEXCEL GEOGRAPHY A</span><h2>Your pathway</h2><p>Choose your school’s exam options. The UK landscape introduction is shared. Optional landscape lessons follow your choices; saved progress is kept when options change.</p><fieldset><legend>Choose two landscapes</legend>${[['coasts','Coasts'],['rivers','Rivers'],['glaciers','Glaciated uplands']].map(([id,label])=>`<label class="geo-option"><input type="checkbox" name="gLandscape" value="${id}" ${p?.landscapes.includes(id)?'checked':''}>${label}</label>`).join('')}</fieldset>${[['resource','Resource management',[['energy','Energy'],['water','Water']]],['physical','Physical fieldwork',[['rivers','Rivers'],['coasts','Coasts']]],['human','Human fieldwork',[['urban','Central/inner urban area'],['rural','Rural settlement']]]].map(([name,label,opts])=>`<fieldset><legend>${label}</legend>${opts.map(([id,v])=>`<label class="geo-option"><input type="radio" name="g-${name}" value="${id}" ${p?.[name]===id?'checked':''}>${v}</label>`).join('')}</fieldset>`).join('')}<p id="gPathError" role="status"></p><button class="primary" id="gSavePath">Save pathway</button>`);document.getElementById('gSavePath').onclick=()=>{const p={landscapes:[...document.querySelectorAll('[name=gLandscape]:checked')].map(x=>x.value)};for(const name of ['resource','physical','human'])p[name]=document.querySelector(`[name=g-${name}]:checked`)?.value;if(!validPath(p)){document.getElementById('gPathError').textContent='Select exactly two landscapes and one option in each other group.';return;}s.pathway=p;if(!eligibleGeography(lesson(),p))s.lessonId=lessons[0].id;mode='lesson';save();closeModal();render();};}
 function startReview(topicId){const allowed=new Set(dueConcepts(s)),qs=available().filter(l=>typeof topicId!=='string'||l.topicId===topicId).flatMap(l=>[...l.check,...l.practice]),seen=new Set();const list=qs.filter(q=>{if(!allowed.has(q.concept)||seen.has(q.concept))return false;seen.add(q.concept);return true;});if(!list.length){modal('<h2>Nothing due yet</h2><p>Your missed or due concepts will return here. Continue learning for now.</p>');return;}run={questions:list,answers:{},index:0};mode='review';closeModal();render();}
 function openSources(){cancelQuestionAdvance();modal(`<h2>Sources & model notes</h2><p>Pearson Edexcel Geography A1GA0, Issue5, September2025; checked23October2026. This lesson maps to ${contextLesson().refs.join(', ')}.</p><p><a href="${source}" target="_blank" rel="noopener">Official specification ↗</a></p><p><a href="https://www.bgs.ac.uk/discovering-geology/rocks-and-minerals/" target="_blank" rel="noopener">BGS rocks and minerals ↗</a> · <a href="https://www.bgs.ac.uk/discovering-geology/geological-processes/relief/" target="_blank" rel="noopener">BGS relief ↗</a> · <a href="https://www.bgs.ac.uk/datasets/bgs-geology/" target="_blank" rel="noopener">BGS geology mapping ↗</a></p><p>Coastal process references: <a href="https://www.bgs.ac.uk/discovering-geology/earth-hazards/landslides/" target="_blank" rel="noopener">BGS landslides</a> · <a href="https://www.noaa.gov/jetstream/ocean/waves" target="_blank" rel="noopener">NOAA waves</a> · <a href="https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/storms/storm-surge" target="_blank" rel="noopener">Met Office storm surge</a>. Coastal animations compress time; retreat data are invented teaching examples, not site measurements.</p><p>Named coast: <a href="https://www.bgs.ac.uk/discovering-geology/maps-and-resources/office-geology/ballard-down/" target="_blank" rel="noopener">BGS Ballard Down</a> · <a href="https://www.rgs.org/schools/resources-for-schools/jurassic-coast-of-dorset-and-east-devon/swanage-coastal-management" target="_blank" rel="noopener">RGS Swanage</a> · <a href="https://environment.data.gov.uk/shoreline-planning/unit/SMP15/N.1" target="_blank" rel="noopener">Environment Agency New Swanage N.1</a>. Checked23October2026. Old Harry photo: Nilfanion/Wikimedia UK,17October2013,CC BY-SA4.0, unchanged; full credit beside image. These are named-place sources, not proof that all school fieldwork/map/writing evidence is complete.</p><p>River sources: <a href="https://teesvalleymuseums.org/blog/post/the-river-tees/" target="_blank" rel="noopener">Tees Valley Museums</a> · <a href="https://www.field-studies-council.org/resources/14-16-%20geography/rivers/fieldwork/" target="_blank" rel="noopener">FSC river measurement</a> · <a href="https://environment.data.gov.uk/flood-monitoring/id/stations/F3504.html" target="_blank" rel="noopener">EA Barnard Castle stage</a> · <a href="https://weather.metoffice.gov.uk/learn-about/met-office-for-schools/other-content/other-resources/extreme-weather" target="_blank" rel="noopener">Met Office weather</a>. River width/area/speed cases are invented teaching examples. The two genuine dated EA levels are stage in metres, not discharge, live conditions or a continuous hydrograph. Authentic BGS-map and paired UK weather analysis remain separate tasks.</p><p>River landforms: <a href="https://www.raby.co.uk/high-force/waterfall/history/" target="_blank" rel="noopener">Raby High Force geology</a> · <a href="https://northpennines.org.uk/location/high-force-geosite/" target="_blank" rel="noopener">North Pennines geosite</a>. Genuine High Force photo: Sandy Gerrard / Geograph,29September2021,CC BY-SA2.0, unchanged. <a href="https://consult.environment-agency.gov.uk/east-midlands/flood-risk-management/" target="_blank" rel="noopener">EA flood storage and washlands</a>. Hydrographs are invented hourly comparisons, not measured UK events. Reading them does not demonstrate drawing skill; real OS/GIS and constructed evidence remain separate.</p><p>Glaciation: <a href="https://www.rgs.org/schools/resources-for-schools/glaciation-and-geological-timescales/how-glaciers-shape-the-land-and-what-they-leave-behind" target="_blank" rel="noopener">RGS glacial processes</a> · <a href="https://www.bgs.ac.uk/discovering-geology/geological-processes/weathering/" target="_blank" rel="noopener">BGS weathering</a> · <a href="https://weather.metoffice.gov.uk/guides/mountain/forecast" target="_blank" rel="noopener">Met Office mountain weather</a>. Diurnal temperatures are invented, not observed UK data. Real OS recognition, weather analysis and constructed explanations remain separate. Tees case: <a href="https://www.nwg.co.uk/globalassets/corporate/environment-pdfs/drought-plan/nw/nw-final-drought-plan---may-2022---published-version.pdf" target="_blank" rel="noopener">Northumbrian Water2022 plan</a> documents Cow Green flow support; this is a dated source, not live operating data.</p><p>Further glacial landforms: <a href="https://www.nature.scot/landforms-and-geology/scotlands-rocks-landforms-and-soils/landforms/ice-age-landforms/ice-transported-debris" target="_blank" rel="noopener">NatureScot transported debris</a> · <a href="https://www.antarcticglaciers.org/glacial-geology/glacial-landforms/glacial-erosional-landforms/roches-moutonnees/" target="_blank" rel="noopener">Glaciologist explanation of roche moutonnée</a>. Land use: <a href="https://www.forestresearch.gov.uk/publications/designing-and-managing-forests-and-woodlands-to-reduce-flood-risk/" target="_blank" rel="noopener">Forest Research woodland and runoff</a> · <a href="https://naturalresources.wales/guidance-and-advice/business-sectors/farming/how-to-prepare-a-farm-or-agricultural-land-for-flooding/?lang=en" target="_blank" rel="noopener">NRW compaction and runoff</a>. Schematic landforms and land-cover comparisons are not genuine OS/GIS layers. Drumlin formation varies; no universal mechanism or measured rate is implied.</p><p>Upland development and named landscape: <a href="https://www.lakedistrict.gov.uk/learning/forteachers/teachers-resources/ks2water" target="_blank" rel="noopener">National Park Thirlmere water history</a> · <a href="https://lakedistrict.gov.uk/protect/landscape-and-heritage/archaeology-and-historic-landscape/geology-and-geomorphology/" target="_blank" rel="noopener">National Park geology</a> · <a href="https://www.nationaltrust.org.uk/visit/lake-district/the-langdales/stickle-tarn-trail" target="_blank" rel="noopener">National Trust Stickle Ghyll hydro</a> · <a href="https://www.fixthefells.co.uk/what-we-do/" target="_blank" rel="noopener">Fix the Fells</a> · <a href="https://www.cumbriawildlifetrust.org.uk/armboth-fell-peatland-restoration" target="_blank" rel="noopener">Armboth restoration</a>. Thirlmere photo:Jorge Franganillo,10August2012,CC BY2.0,unchanged; full credit beside image. Water budgets are invented, not Thirlmere data; hydro example is Langdale, not a claim of generation at Thirlmere. Source check23October2026. Genuine OS/GIS and constructed evidence remain separate.</p><p>Weather and past climate: <a href="https://weather.metoffice.gov.uk/learn-about/weather/atmosphere/global-circulation-patterns" target="_blank" rel="noopener">Met Office circulation</a> · <a href="https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-currents" target="_blank" rel="noopener">NOAA ocean currents</a> · <a href="https://www.nps.gov/articles/000/quaternary-period.htm" target="_blank" rel="noopener">NPS Quaternary</a> · <a href="https://www.bgs.ac.uk/discovering-geology/climate-change/what-causes-the-earths-climate-to-change/" target="_blank" rel="noopener">BGS natural causes</a> · <a href="https://science.nasa.gov/climate-change/evidence/" target="_blank" rel="noopener">NASA evidence</a> · <a href="https://www.ncei.noaa.gov/news/what-are-proxy-data" target="_blank" rel="noopener">NOAA proxy records</a>. Cells, orbital geometry, timelines and proxy illustrations simplify mechanisms, not measured weather or climate records. Natural past variation does not explain rapid recent warming by itself. Source check23October2026; authentic UK climate charts and constructed evidence remain separate.</p><p>Human climate and UK climate: <a href="https://science.nasa.gov/climate-change/causes/" target="_blank" rel="noopener">NASA greenhouse gases</a> · <a href="https://weather.metoffice.gov.uk/climate-change/effects-of-climate-change" target="_blank" rel="noopener">Met Office impacts</a> · <a href="https://weather.metoffice.gov.uk/climate-change/climate-change-questions" target="_blank" rel="noopener">Regional past climate</a> · <a href="https://www.metoffice.gov.uk/research/climate/maps-and-data/regional-climates" target="_blank" rel="noopener">UK controls</a>. HadCET v2.1.1.0 annual values1659–2025 and30-year arithmetic means, source retrieved23October2026; Central England only, absolute °C, not anomalies or all-UK means.2026provisional data excluded. Data are Crown copyright/OGL3.0, source and raw file linked beside graphs. Reading real line/bar charts is practised; drawing charts, longer proxy analysis and specialist review remain separate.</p><p>UK outline: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth, public domain</a>; generalised country geometry, not geological units.</p><p>Original simplified diagrams: crystal textures, positions, profiles, times and land-use patterns are symbolic. The resistance experiment uses invented teaching values. They are not BGS/OS maps, actual site measurements or forecasts. Real OS-map interpretation, written geographical argument and school fieldwork need separate evidence. Simulations do not replace the required two occasions of fieldwork outside school grounds.</p>`);}
 return {render,stop,openLessons,openMap,openSources,openPathway,startReview,startAssessment:()=>{modal('<h2>Topic assessment is being developed</h2><p>Use each lesson’s independent Check for now.</p>');},getProgress,openProgressLesson:openLesson,reviewTopic:startReview,title:()=>mode==='review'?'Geography review':lesson().title,state:()=>s};
}
